CustomField.formula:
TRIM(
  IF(
    CONTAINS(Name, ":"),
    /* Case 1: has colon -> last segment */
    IF(
      FIND(":", REVERSE(Name)) > 1,
      RIGHT(Name, FIND(":", REVERSE(Name)) - 1),
      ""
    ),
    /* Case 2/3: no colon -> decide Id vs text by a0W prefix */
    IF(
      LEFT(Name, 3) = "a0W",
      "",
      Name
    )
  )
)
